   "cover": "./%E5%86%85%E5%AE%B9/%E5%B8%82%E5%9C%BA%E7%84%9A%E8%AF%80/%E7%A0%96%E7%9A%AE%E5%B8%82%E5%9C%BA%E6%9C%BA%E5%88%B6/00-%E5%86%99%E7%BB%99%E6%96%B0%E6%89%8B%E7%9A%84%E4%B8%80%E5%B0%81%E6%83%85%E4%B9%A6/01-%E7%A0%96%E5%8F%8A%E9%92%A5%E5%8C%99%E8%8E%B7%E5%8F%96/%E7%83%BD%E7%81%AB%E5%9C%B0%E5%B8%A6%E7%A0%B4%E8%AF%91.jpg",
