   "cover": "./%E5%86%85%E5%AE%B9/%E5%B8%82%E5%9C%BA%E7%84%9A%E8%AF%80/%E7%A0%96%E7%9A%AE%E5%B8%82%E5%9C%BA%E6%9C%BA%E5%88%B6/00-%E5%86%99%E7%BB%99%E6%96%B0%E6%89%8B%E7%9A%84%E4%B8%80%E5%B0%81%E6%83%85%E4%B9%A6/02-%E7%A0%96%E7%9A%AE%E8%8E%B7%E5%8F%96%E6%A6%82%E8%A7%88/%E6%A6%82%E7%8E%87%E8%AF%A6%E8%A7%88-MK4.jpg",
