   "cover": "./%E5%86%85%E5%AE%B9/%E5%B8%82%E5%9C%BA%E7%84%9A%E8%AF%80/%E7%A0%96%E7%9A%AE%E5%B8%82%E5%9C%BA%E6%9C%BA%E5%88%B6/00-%E5%86%99%E7%BB%99%E6%96%B0%E6%89%8B%E7%9A%84%E4%B8%80%E5%B0%81%E6%83%85%E4%B9%A6/03-%E7%A3%A8%E6%8D%9F%E4%B8%8E%E6%88%90%E8%89%B2/%E5%A4%96%E8%A7%82%E5%87%BA%E5%94%AE-%E6%88%90%E8%89%B2.jpg",
